    if keys != {"op", "rev", "now"}:
        fail(EXIT_INPUT, "INPUT")
    rev = raw_op["rev"]
    if (
        not isinstance(rev, int)
        or isinstance(rev, bool)
        or not 1 <= rev <= 10 ** 18
    ):
        fail(EXIT_INPUT, "INPUT")
    return ("cb", rev, parse_now(raw_op["now"]))

if name == "ts":
    if keys != {"op", "ttl"}:
