        fail(EXIT_STATE, "STATE")
    if next_rev > 10 ** 18:
        # rev 耗尽：不分配、不改历史。
        fail(EXIT_STATE, "STATE")
    # 校验全部通过，原子替换配置并以 now 重建默认运行态（v7+ 同步
