def digest_of(config):
    """与实现同款：逐层键序紧凑 UTF-8 JSON（非 ASCII 不转义、无末尾
    换行）的 SHA-256 小写十六进制。"""
    canonical = json.dumps(
        config, ensure_ascii=False, separators=(",", ":")
    ).encode("utf-8")
    return hashlib.sha256(canonical).hexdigest()


